// A5Q6 Eve of Destruction. Per-player iterate callback (called as Baal dies): if the player is not yet Completed(0) AND is standing in LEVEL_TheWorldstoneChamber (level id 0x84) and is neither Completed nor RewardAwaits, call Q36_CompleteQuestAndSetStatus to give them the kill. This is the "present at the Baal kill" credit check.
BOOL __fastcall Q36_CheckWorldstoneChamber(::SGAMEDATA * pGame, D2UnitStrc * pUnit, void * pArg) {
    BOOL _bQuestState;
    bool bQuestState;
    /* GetQuestState(QUEST_EveOfDestruction, 0=Completed) — bail if already
                         complete */ D2BitBufferStrc* pQuestRecord = D2Common::Units::GetPlayerData(pUnit)->pQuestRecord[pGame->nDifficulty];
    _bQuestState = D2Common::QuestRecord::GetQuestState(pQuestRecord, QUEST_EveOfDestruction, QUESTSTATE_Completed);
    if (_bQuestState == 1) {
      return 0;
    }

    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    if (!pRoom) {
      return 0;
    }

    D2UnitDataPlayerStrc* pPlayerData2 = D2Common::Units::GetPlayerData(pUnit);
    D2BitBufferStrc* pBitBuffer = pPlayerData2->pQuestRecord[pGame->nDifficulty];
    eD2LevelId eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    /* GetQuestState(QUEST_EveOfDestruction, 0=Completed) — re-check in Worldstone
                         Chamber (lvl 0x84) before crediting */ if (eLevelId != LEVEL_TheWorldstoneChamber) {
      return 0;
    }

    _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_EveOfDestruction, QUESTSTATE_Completed);
    if (_bQuestState) {
      return 0;
    }

    _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_EveOfDestruction, QUESTSTATE_RewardAwaits);
    if (_bQuestState) {
      return 0;
    }

    Q36_CompleteQuestAndSetStatus(pUnit, pBitBuffer, pGame);
    return 0;
}

// A5Q6 Eve of Destruction — BAAL DEATH HANDLER (state-fn slot 8). Fires when Baal is killed. NotifyPlayers(0x13); sets live quest state to 4 and broadcasts; then iterates all players: Q36_CheckWorldstoneChamber (credit those present), Q36_PropagateCompleteToParty (party credit), SetCannotComplete (lock out absentees), Q36_SendCompletionNotification (client FX). Rolls and drops quest gold reward (difficulty-scaled) per player in the chamber, saves char to client, sets nStateFlag=5. Finally spawns the red Baal-death portal/missile (0x271) and toggles the room portal flag — the exit portal to town.
void __fastcall Q36_Callback_08_CompleteQuest(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    BOOL _bQuestCompleted;
    bool bQuestCompleted;
    int nBaseGold;
    int32_t nGoldAmount;
    uint32_t nPosY;
    uint32_t nPosX;
    int i;
    uint32_t nGoldCap;
    ::SGAMEDATA* pGame;
    bool bPlayerNotYetComplete;
    D2QuestDataA5Q6Strc* pA5Q6Data = pQuestData->pQuestSpecificData.pA5Q6;
    NotifyPlayersAboutEvent(pQuestData->pGame, 0x13);
    if (pQuestData->bIsNotIntroduction != '\0') {
      D2RoomStrc* pRoom;
      bPlayerNotYetComplete = false;
      pRoom = D2Common::Units::UNITS_GetRoom(pQuestArgs->pTarget);
      pA5Q6Data->pRoomTarget = (uint8_t*)pRoom;
      if (!pRoom) {
        return;
      }

      QUEST_SetStateAndBroadcast(pQuestData, 4, nullptr, (::fpExecuteOnUnitFunction)SendQuestBitsIfNeeded, true);
      if (pQuestArgs->pPlayer) {
        if (pQuestData->bIsNotIntroduction != '\0') {
          pGame = pQuestArgs->pGame;
          /* GetQuestState(QUEST_EveOfDestruction, 0=Completed) — track if the
                         triggering player had not yet completed (gates gold reward) */ D2BitBufferStrc* pQuestRecord = D2Common::Units::GetPlayerData(pQuestArgs->pPlayer)->pQuestRecord[pGame->nDifficulty];
          _bQuestCompleted = D2Common::QuestRecord::GetQuestState(pQuestRecord, QUEST_EveOfDestruction, QUESTSTATE_Completed);
          if (!_bQuestCompleted) {
            bPlayerNotYetComplete = true;
          }
        }

        pA5Q6Data->nPlayersInWorldstone = 0;
        UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestArgs->pGame, 0, pQuestArgs->pTarget, (::fpExecuteOnUnitFunction)Q36_CheckWorldstoneChamber);
        UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestArgs->pGame, 0, pQuestArgs->pTarget, (::fpExecuteOnUnitFunction)Q36_PropagateCompleteToParty);
        UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestArgs->pGame, 0, pQuestArgs->pTarget, (::fpExecuteOnUnitFunction)SetCannotComplete);
        UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestArgs->pGame, 0, pQuestArgs->pTarget, (::fpExecuteOnUnitFunction)Q36_SendCompletionNotification);
        if (bPlayerNotYetComplete) {
          nBaseGold = (uint32_t)pQuestData->pGame->nDifficulty * 6000;
          nGoldCap = nBaseGold + 3000;
          if (nGoldCap >= 0xffff) {
            nGoldCap = 0xffff;
          }

          for (i = 0; i < pA5Q6Data->nPlayersInWorldstone; i++) {
            QUEST_StubEmpty(pQuestData, pQuestArgs, 0x5f);
            nGoldAmount = D2Client::SEED_RollRange(GetQuestControlSeed(pQuestData->pGame), nBaseGold + 0x5dc, nGoldCap);
            ITEMS::Items::Drop::DROP_SpawnGoldOnGround(pQuestData->pGame, pQuestArgs->pTarget, nGoldAmount);
          }
        }

        GAME::Server::SendSaveFileToClient(pQuestData->pGame);
      }
      if (pQuestData->nStateFlag != 5) {
        pQuestData->nStateFlag = 5;
      }
    }

    D2UnitStrc* pTargetUnit = pQuestArgs->pTarget;
    eD2UnitType eUnitType = pTargetUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nPosY = pTargetUnit->pPath.pStaticPath->nPosY;
    } else if (pTargetUnit->pPath.pDynamicPath) {
      nPosY = D2Common::PATH::DynamicPath::GetYPos(pTargetUnit->pPath.pDynamicPath);
    } else {
      nPosY = 0;
    }

    pTargetUnit = pQuestArgs->pTarget;
    eD2UnitType eTargetUnitType = pTargetUnit->eUnitType;
    if (eTargetUnitType == UNIT_OBJECT || (int)eTargetUnitType > 3 && (int)eTargetUnitType <= 5) {
      nPosX = pTargetUnit->pPath.pStaticPath->nPosX;
    } else if (pTargetUnit->pPath.pDynamicPath) {
      nPosX = D2Common::PATH::DynamicPath::GetXPos(pTargetUnit->pPath.pDynamicPath);
    } else {
      nPosX = 0;
    }

    D2UnitStrc* pMissile = SKILLS::SkillsServer::SKILLS_CreateMissileAtTarget(pQuestArgs->pGame, pQuestArgs->pTarget, SKILL_Attack, 1, MISSILE_BaalfxControl, nPosX, nPosY);
    if (!pMissile) {
      return;
    }

    D2RoomStrc* pRoom_00 = D2Common::Units::UNITS_GetRoom(pMissile);
    D2Common::DUNGEON::Dungeon::ToggleHasPortalFlagRoom(pRoom_00, 0);
}

