// A5Q6 Eve of Destruction (state-fn slot 3). Quest-accept / "talked to Tyrael" handler. On gossip index 0x6d sends the special quest packet. When the activation index==0x6d and live nStateFlag==2: if player not Completed/RewardAwaits, advance live quest to nStateFlag 3, broadcast "in progress" (state 1), and propagate sub-steps to all players (SetStep0x2And0x3). For index>0x82 advances to state 2. Drives the player's acceptance of the final-assault quest.
// @sourcefile d:\diablo2\Diablo2\Source\D2Game/Quests/a5q6.cpp
void __fastcall Q36_Callback03_ChangedLevel(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    BOOL _bQuestState;
    bool bQuestState;
    ::SGAMEDATA* pGame;
    D2BitBufferStrc* pBitBuffer;
    D2GossipTextStrc* pTextControl = (D2GossipTextStrc*)pQuestArgs->sQuestArgs.sNpcActivate.pTextControl;
    int nIndex = pQuestArgs->sQuestArgs.sNpcActivate.nIndex;
    if (nIndex == 0x6d) {
      Q36_SendQuestSpecialPacket(pQuestArgs->pPlayer, pQuestArgs->pGame);
    }
    if (pTextControl == (D2GossipTextStrc*)0x6d) {
      D2UnitDataPlayerStrc* pPlayerData;
      QUESTGUID_RemovePlayerFromQuest(pQuestData, pQuestArgs);
      if (pQuestData->nStateFlag == 2) {
        pGame = pQuestArgs->pGame;
        pPlayerData = D2Common::Units::GetPlayerData(pQuestArgs->pPlayer);
        pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
        /* GetQuestState(QUEST_EveOfDestruction, ==1 Completed) — abort
                         accept-progression if already done */ _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Completed);
        if (_bQuestState == 1) {
          return;
        }

        /* GetQuestState(QUEST_EveOfDestruction, ==1 RewardAwaits) — abort
                         accept-progression if reward pending */ _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_RewardAwaits);
        if (_bQuestState == 1) {
          return;
        }

        QUEST_SetStateFlag(pQuestData, 3, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a5q6.cpp", 0x272);
        if (pQuestData->nStateFlagPrev != 1) {
          pQuestData->nQuestPacketFlags = '\0';
          QUEST_SetStateAndBroadcast(pQuestData, 1, nullptr, (::fpExecuteOnUnitFunction)SendQuestBitsIfNeeded, true);
        }

        UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestData->pGame, 0, nullptr, (::fpExecuteOnUnitFunction)SetStep0x2And0x3);
      }
    }
    if (nIndex < 0x83) {
      return;
    }
    if (pQuestData->bIsNotIntroduction != '\0' && pQuestData->nStateFlagPrev < 2) {
      pQuestData->nQuestPacketFlags = '\0';
      QUEST_SetStateAndBroadcast(pQuestData, 2, nullptr, (::fpExecuteOnUnitFunction)SendQuestBitsIfNeeded, true);
    }

    UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestData->pGame, 0, nullptr, (::fpExecuteOnUnitFunction)SetStep0x2And0x3);
}

// A5Q6 Eve of Destruction. fpActiveFilter: returns true if the given NPC/monster class should currently offer this quest's gossip (a "!" indicator). True for the Ancients statues 0x219..0x21b once A5Q5 cleared them and Anya not yet transformed; or, once quest Completed, for act-V NPCs (0x1ff/0x200/0x201/0x203/0x208/0x209) whose corresponding journal Step bit (Step0x04..Step0x09) is NOT yet set — i.e. the player still has someone to talk to about Baal. Class 0x208 also suppressed once Step0x10 set.
bool __fastcall Q36_ActiveFilter(D2QuestDataStrc * pQuestData, eD2MonsterClassId nTargetClassId, D2UnitStrc * pUnit, D2BitBufferStrc * pBitBuffer, D2UnitStrc * pUnitEx) {
    bool bQuestState;
    eD2QuestState eQuestState;
    if ((uint32_t)(nTargetClassId - MonsterUnitAncientStatue1) <= 2) {
      D2QuestDataStrc* pA5Q5QuestData;
      pA5Q5QuestData = GetQuestDataByQuestNoInternal(pQuestData->pGame, QUESTINT_RiteOfPassage);
      if (pA5Q5QuestData && pA5Q5QuestData->pQuestSpecificData.pA5Q5->bAncientsSpawned && !pA5Q5QuestData->pQuestSpecificData.pA5Q5->nAncientsAlive && pQuestData->nStateFlag == 1 && !pQuestData->pQuestSpecificData.pA5Q6->bAnyaTransformed) {
        return true;
      }
    }

    BOOL BVar1 = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_EveOfDestruction, QUESTSTATE_Completed);
    if (!(BVar1 && true)) {
      return false;
    }

    switch (nTargetClassId) {
      case MonsterUnitLarzuk:
        eQuestState = QUESTSTATE_Step0x04;
      break;
      case MonsterUnitDrehya1:
        eQuestState = QUESTSTATE_Step0x09;
      break;
      case MonsterUnitMalah:
        eQuestState = QUESTSTATE_Step0x06;
      break;
      default:
        return false;
      case MonsterUnitQualkehk:
        eQuestState = QUESTSTATE_Step0x08;
      break;
      case MonsterUnitDeckardCain6:
        /* GetQuestState(QUEST_EveOfDestruction, 0xa=Step0x10) — NPC 0x208: suppress
                         gossip once final Step0x10 (left act) set */ BVar1 = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_EveOfDestruction, QUESTSTATE_Step0x10);
      if (BVar1) {
        return false;
      }

      eQuestState = QUESTSTATE_Step0x05;
      break;
      case MonsterUnitTyrael3:
        eQuestState = QUESTSTATE_Step0x07;
    }

    /* GetQuestState(QUEST_EveOfDestruction, eStep) — per-NPC Step bit
                         (0x1ff->Step0x04, 0x200->Step0x09, 0x201->Step0x06, 0x203->Step0x08,
                         0x208->Step0x05, 0x209->Step0x07); offer gossip only if NOT yet set */ BVar1 = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_EveOfDestruction, eQuestState);
    if (BVar1) {
      return false;
    }

    return true;
}

// A5Q6 Eve of Destruction. fpSequenceFilter (linked to prerequisite QUEST_PrisonOfIce / Anya rescue). When this quest is active and not yet started (nStateFlag==0), latch bAnyaTransformed, force live nStateFlag=2, broadcast "in progress" (state 1), and push sub-steps to all players. Kicks the final quest into motion once Anya/prereq conditions are met.
bool __fastcall Q36_SequenceFilter(D2QuestDataStrc * pQuestData) {
    D2QuestDataStrc* pA5Q6EveQuestData = GetQuestDataByQuestNoInternal(pQuestData->pGame, QUESTINT_EveOfDestruction);
    if (!(pA5Q6EveQuestData->bIsNotIntroduction != '\0' && !pA5Q6EveQuestData->nStateFlag)) {
      return true;
    }

    pA5Q6EveQuestData->pQuestSpecificData.pA5Q6->bAnyaTransformed = 1;
    pA5Q6EveQuestData->nStateFlag = 2;
    pA5Q6EveQuestData->nQuestPacketFlags = '\0';
    QUEST_SetStateAndBroadcast(pA5Q6EveQuestData, 1, nullptr, (::fpExecuteOnUnitFunction)SendQuestBitsIfNeeded, true);
    UNIT::SUnit::IteratePlayerOrMonsterUnits(pA5Q6EveQuestData->pGame, 0, nullptr, (::fpExecuteOnUnitFunction)SetStep0x2And0x3);
    return true;
}

// A5Q6 Eve of Destruction (state-fn slot 0xe). If the player's quest is Completed(0), set Step0x10 (the "departed act V / acknowledged completion" bit). Small post-completion bookkeeping callback.
void __fastcall Q36_Callback14_PlayerJoinedGame(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    BOOL _bQuestCompleted;
    bool bQuestCompleted;
    ::SGAMEDATA* pGame = pQuestArgs->pGame;
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pQuestArgs->pPlayer);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    /* GetQuestState(QUEST_EveOfDestruction, 0=Completed) — only set Step0x10 once
                         quest complete */ _bQuestCompleted = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Completed);
    if (!_bQuestCompleted) {
      return;
    }

    /* SetQuestState(QUEST_EveOfDestruction, 0xa=Step0x10) — mark act-V completion
                         acknowledged */ D2Common::QuestRecord::SetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Step0x10);
}

// A5Q6 Eve of Destruction (state-fn slot 0xd). Quest-load / late-join reconciliation. If the player has NOT completed (not Completed, not FinishedInPreviousGame, not RewardAwaits) but has progressed (Step0x03 set, or Step0x02 -> mark bAnyaTransformed): restore live quest nStateFlag to 3 (in-progress). If already completed/finished: set Step0x10 and push client status 5 (act done). Reconstructs quest progression for a joining/loading player.
// @sourcefile d:\diablo2\Diablo2\Source\D2Game/Quests/a5q6.cpp
void __fastcall Q36_Callback13_PlayerStartedGame(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    BOOL _bQuestState;
    bool bQuestState;
    ::SGAMEDATA* pGame = pQuestArgs->pGame;
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pQuestArgs->pPlayer);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    /* GetQuestState(QUEST_EveOfDestruction, 0=Completed) — if done, jump to set
                         Step0x10 + status 5 */ _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Completed);
    /* GetQuestState(QUEST_EveOfDestruction, 0xf=FinishedInPreviousGame) — also
                         treat as done */ if (!_bQuestState) {
      _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_FinishedInPreviousGame);
      if (!_bQuestState) {
        /* GetQuestState(QUEST_EveOfDestruction, 1=RewardAwaits) — if pending reward,
                         stop (no in-progress restore) */ _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_RewardAwaits);
        if (_bQuestState == 1) {
          return;
        }

        /* GetQuestState(QUEST_EveOfDestruction, 3=Step0x03) — progressed: restore
                         live nStateFlag=3 */ _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Step0x03);
        if (_bQuestState != 1) {
          /* GetQuestState(QUEST_EveOfDestruction, 2=Step0x02) — quest-started: also
                         restore + set bAnyaTransformed */ _bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Step0x02);
          if (_bQuestState != 1) {
            return;
          }

          pQuestData->pQuestSpecificData.pA5Q6->bAnyaTransformed = 1;
        }

        pQuestData->nStateFlagPrev = 1;
        pQuestData->nStateFlag = 3;
        return;
      }
    }

    /* SetQuestState(QUEST_EveOfDestruction, 0xa=Step0x10) — final "left act V"
                         bit for already-completed loader */ D2Common::QuestRecord::SetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Step0x10);
    uint32_t nDifficulty = (uint32_t)pQuestData->pGame->nDifficulty;
    GAME::Clients::SetClientStatus(UNIT::SUnit::SUNIT_GetClient(pQuestArgs->pPlayer, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a5q6.cpp", 0x2fe), 5, nDifficulty);
}

// A5Q6 Eve of Destruction — quest INIT (nInitNo=4). Allocates the 0xa8-byte A5Q6 quest-specific struct, wires up the state-handler vtable (slots: 0=Callback_00 gossip, 2=Callback_02 tentacle, 3=Callback_03 accept, 8=Callback_08 Baal death, 0xa=Callback_10 leave, 0xb=Callback_11 dialog, 0xd=Callback_13 load, 0xe=Callback_14), sets the act-V NPC gossip table (monstats 0x1ff/0x208/0x201/0x203/0x200), nQuestIdReal=QUEST_EveOfDestruction, fpActiveFilter=Q36_ActiveFilter, fpSequenceFilter=Q36_SequenceFilter, nSequenceQuestId=QUEST_PrisonOfIce. Zeroes the struct + GUID list.
// @sourcefile d:\diablo2\Diablo2\Source\D2Game/Quests/a5q6.cpp
void __fastcall Q36_InitData(D2QuestDataStrc * pQuestData) {
    memset(&pQuestData->sStateFunctions, 0, 0x3c);
    ::SGAMEDATA* pGame = pQuestData->pGame;
    pQuestData->sStateFunctions.fpQuestStateHandler[10] = Q36_Callback10_PlayerLeavesGame;
    pQuestData->sStateFunctions.fpQuestStateHandler[3] = Q36_Callback03_ChangedLevel;
    pQuestData->sStateFunctions.fpQuestStateHandler[8] = Q36_Callback_08_CompleteQuest;
    pQuestData->sStateFunctions.fpQuestStateHandler[0] = Q36_Callback00_NpcActivate;
    pQuestData->sStateFunctions.fpQuestStateHandler[2] = Q36_Callback02_NpcDeactivate;
    pQuestData->sStateFunctions.fpQuestStateHandler[0xb] = Q36_Callback11_ScrollMessage;
    pQuestData->sStateFunctions.fpQuestStateHandler[0xd] = Q36_Callback13_PlayerStartedGame;
    pQuestData->sStateFunctions.fpQuestStateHandler[0xe] = Q36_Callback14_PlayerJoinedGame;
    pQuestData->pNpcMessages = &A5Q6::aNpcGossipData;
    pQuestData->bIsActive = '\x01';
    pQuestData->nStateFlag = 0;
    D2QuestDataA5Q6Strc* pQuestSpecificData = D2_NEW_POOL_AT(pGame->pMemoryPool, D2QuestDataA5Q6Strc, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a5q6.cpp", 0x329);
    pQuestData->pQuestSpecificData.pA5Q6 = pQuestSpecificData;
    pQuestData->nQuestIdReal = QUEST_EveOfDestruction;
    pQuestData->fpStatusFilter = 0;
    pQuestData->nInitNo = 4;
    pQuestData->fpActiveFilter = (QUESTACTIVE)Q36_ActiveFilter;
    pQuestData->fpSequenceFilter = Q36_SequenceFilter;
    pQuestData->nSequenceQuestId = QUEST_PrisonOfIce;
    memset(pQuestSpecificData, 0, 0xa8);
    QUESTGUID_SetPlayerCountToZero(&pQuestSpecificData->sQuestGUID);
    pQuestSpecificData->nField_0x94 = 1;
    pQuestSpecificData->nField_0x9C = 1;
}

// A5Q6 Eve of Destruction. Sets bStairsOpened on the quest struct (the descent into the Worldstone Chamber is opened); if quest is active and not yet at state 3, advance live nStateFlag to 3 and broadcast. Called when the player opens the path down to Baal.
void __fastcall SetFlagToOpenedStairs(::SGAMEDATA * pGame) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_EveOfDestruction);
    if (!pQuestData) {
      return;
    }

    pQuestData->pQuestSpecificData.pA5Q6->bAcceptedQuest = 1;
    if (!(pQuestData->bIsNotIntroduction != '\0' && pQuestData->nStateFlagPrev < 3)) {
      return;
    }

    pQuestData->nQuestPacketFlags = '\0';
    QUEST_SetStateAndBroadcast(pQuestData, 3, nullptr, (::fpExecuteOnUnitFunction)SendQuestBitsIfNeeded, true);
}

// A5Q6 Eve of Destruction. Returns 0 if the quest has been accepted (bAcceptedQuest) — i.e. Baal's lair entry is unlocked — else 1. Effectively "is Baal still gated / not yet reachable". Gate check for the Worldstone descent.
BOOL __fastcall Q36_IsBaalAlive(::SGAMEDATA * pGame) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_EveOfDestruction);
    if (pQuestData && pQuestData->pQuestSpecificData.pA5Q6->bAcceptedQuest == 1) {
      return 0;
    }

    return 1;
}

// A5Q6 Eve of Destruction. Object init fn 75: tags the object with the quest's barricade-coord field then sets that field to 2 (one-time init flag). Worldstone-area quest object setup.
void __fastcall Objects_InitFn75(D2ObjectInitFnArg * pInitArg) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pInitArg->pGame, QUESTINT_EveOfDestruction);
    D2QuestDataA5Q6Strc* pA5Q6SpecificData = pQuestData->pQuestSpecificData.pA5Q6;
    D2Common::Units::SetupUpdateFlag(pInitArg->pObject, pA5Q6SpecificData->nField_0x94);
    pA5Q6SpecificData->nField_0x94 = 2;
}

// A5Q6 Eve of Destruction. Operate-fn for the stairway between LEVEL_ThroneOfDestruction and LEVEL_TheWorldstoneChamber. In the Throne with quest accepted -> descend to the Worldstone Chamber (Baal's lair); otherwise -> go (back) up to the Throne of Destruction.
BOOL __fastcall OBJOP_A5Q6_WorldstoneLevelTransition(D2ObjectOperateFnArg * pOperation) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pOperation->sArg.pGame, QUESTINT_EveOfDestruction);
    if (!pQuestData) {
      return 0;
    }

    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pOperation->pAttacker);
    if (!pRoom) {
      return 0;
    }

    eD2LevelId eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    if (eLevelId == LEVEL_ThroneOfDestruction) {
      if (pQuestData->pQuestSpecificData.pA5Q6->bAcceptedQuest == 1) {
        GAME::Level::InitLevel(pOperation->sArg.pGame, pOperation->pAttacker, LEVEL_TheWorldstoneChamber, 0xb);
        return 0;
      }
    } else {
      GAME::Level::InitLevel(pOperation->sArg.pGame, pOperation->pAttacker, LEVEL_ThroneOfDestruction, 0);
    }

    return 0;
}

// A5Q6 Eve of Destruction. Object init fn 77: tags the object with the quest's item-count field then sets it to 2 (marks Tyrael's red end-portal as spawned/active). Pairs with OBJOP_A5Q6_TyraelPortalToEnd which only operates when count==2.
void __fastcall Objects_InitFn77(D2ObjectInitFnArg * pInitArg) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pInitArg->pGame, QUESTINT_EveOfDestruction);
    D2QuestDataA5Q6Strc* pQuestSpecificA1Q3 = pQuestData->pQuestSpecificData.pA5Q6;
    D2Common::Units::SetupUpdateFlag(pInitArg->pObject, pQuestSpecificA1Q3->nField_0x9C);
    pQuestSpecificA1Q3->nField_0x9C = 2;
}

// A5Q6 Eve of Destruction. Operate-fn for Tyrael's red portal in the Worldstone Chamber (after Baal dies). Only active when quest-specific nQuestItemCount==2 (portal spawned). If the player has NOT yet JustCompleted -> just play attach-sound event 0x13. If JustCompleted -> warp the player to LEVEL_Harrogath (town), save char, clear interaction, send 0x61 CanGoToAct(7), and set Step0x10. This is the trip back to town that ends the game.
// @sourcefile d:\diablo2\Diablo2\Source\D2Game/Quests/a5q6.cpp
BOOL __fastcall OBJOP_A5Q6_TyraelPortalToEnd(D2ObjectOperateFnArg * pOperation) {
    int32_t nTradeTick;
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pOperation->sArg.pGame, QUESTINT_EveOfDestruction);
    if (pQuestData->pQuestSpecificData.pA5Q6->nField_0x9C != 2) {
      return 0;
    }

    ::SGAMEDATA* pGame = pOperation->sArg.pGame;
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pOperation->pAttacker);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    BOOL bJustCompleted = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_EveOfDestruction, QUESTSTATE_JustCompleted);
    if (bJustCompleted) {
      D2ClientStrc* pClient;
      GAME::Level::InitLevel(pOperation->sArg.pGame, pOperation->pAttacker, LEVEL_Harrogath, 0);
      pClient = UNIT::SUnit::SUNIT_GetClient(pOperation->pAttacker, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a5q6.cpp", 0x39b);
      pPlayerData = D2Common::Units::GetPlayerData(pOperation->pAttacker);
      GAME::Server::SendSaveFileToClient(pQuestData->pGame);
      if (pClient) {
        nTradeTick = PLAYER::Player::GetPlayerTradeTickOrBusy(pOperation->pAttacker);
        if (!nTradeTick) {
          UNIT::SUnit::ClearInteractInfo(pOperation->pAttacker);
          pPlayerData->dwTradeTick = 1;
          GAME::SCmd::NET_D2GS_SERVER_Send_0x61_CanGoToAct(pClient, 7);
          /* SetQuestState(QUEST_EveOfDestruction, 0xa=Step0x10) — mark "returned to
                         town via Tyrael's portal" */ D2Common::QuestRecord::SetQuestState(pBitBuffer, pQuestData->nQuestIdReal, QUESTSTATE_Step0x10);
          return 0;
        }
      }
    } else {
      UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pOperation->pAttacker, 0x13, pOperation->pAttacker);
    }

    return 0;
}

// A5Q6 Eve of Destruction object-init fn 79. One-time (guarded by init flag): rolls up to 10 times for a random MonStats id with zoo!=0 and stores it in the quest-specific struct as the quest's random monster seed; on failure falls back to id 0. After latching the init flag, broadcasts the quest-special packet to all players via Q36_SendQuestSpecialPacketCallback.
void __fastcall Objects_InitFn79(D2ObjectInitFnArg * pInitArg) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pInitArg->pGame, QUESTINT_EveOfDestruction);
    D2QuestDataA5Q6Strc* pQuestSpecificA1Q4 = pQuestData->pQuestSpecificData.pA5Q6;
    if (pQuestSpecificA1Q4->field_0xA0 != '\0') {
      return;
    }

    int nMonStatsSize = sgptDataTable->nTxtMonStatsSize;
    int nAttempt = 0;
    do {
      int32_t nRolledMonId;
      if (nAttempt >= 10) {
        break;
      }

      nRolledMonId = D2Client::SEED_RollRange(GetQuestControlSeed(pQuestData->pGame), 1, nMonStatsSize);
      nAttempt++;
      pQuestSpecificA1Q4->nQuestFlags = nRolledMonId;
      if (nRolledMonId >= 0 && nRolledMonId < sgptDataTable->nTxtMonStatsSize && sgptDataTable->pTxtMonStats + nRolledMonId && (uint8_t)*((uint8_t*)&sgptDataTable->pTxtMonStats[nRolledMonId] + 0xe) & gadwBitMasks[6]) {
        pQuestSpecificA1Q4->field_0xA0 = '\x01';
      }
    } while (pQuestSpecificA1Q4->field_0xA0 == '\0');

    if (pQuestSpecificA1Q4->field_0xA0 == '\0') {
      pQuestSpecificA1Q4->field_0xA0 = '\x01';
      pQuestSpecificA1Q4->nQuestFlags = 0;
      if (pQuestSpecificA1Q4->field_0xA0 == '\0') {
        return;
      }
    }

    UNIT::SUnit::IteratePlayerOrMonsterUnits(pInitArg->pGame, 0, nullptr, (::fpExecuteOnUnitFunction)Q36_SendQuestSpecialPacketCallback);
}

// A5Q6 Eve of Destruction. Spawns Tyrael (monster class 0x209... note: 0x209 here is the spawned NPC) as a Neutral monster ~5 tiles from the given unit in the Worldstone Chamber. Tyrael appears after Baal's death to open the portal home.
void __fastcall SpawnTyrael(::SGAMEDATA * pGame, D2RoomStrc * pRoom, D2UnitStrc * pUnit) {
    POINT ptCoords;
    D2RoomStrc* pSpawnRoom = 0;
    D2Common::Units::GetCoords(pUnit, &ptCoords);
    ptCoords.x += -5;
    ptCoords.y += -5;
    FindSpawnableLocation(pRoom, &ptCoords, 5, 0x400, &pSpawnRoom, 0x13, 100);
    if (!pSpawnRoom) {
      return;
    }

    Monster::Create::SpawnMonsterAtRoomPos(pGame, pSpawnRoom, ptCoords.x, ptCoords.y, 0x209, eD2MonsterAnimMode_ns::Neutral, 4, 0x42);
}

